declare(strict_types=1);require_once __DIR__.'/bootstrap.php';require_login();$pdo=db();$format=strtolower((string)($_GET['format']??'csv'));$q=trim((string)($_GET['q']??''));$state=(string)($_GET['state']??'');$component=(int)($_GET['component']??0);$year=(string)($_GET['year']??'');$where=[];$args=[];if($q!==''){$where[]='(p.project_code LIKE ? OR p.project_name LIKE ? OR si.code LIKE ? OR si.name LIKE ? OR s.country LIKE ?)';for($i=0;$i<5;$i++)$args[]='%'.$q.'%';}if(in_array($state,['draft','review','approval','approved'],true)){$where[]='s.state=?';$args[]=$state;}if($component){$where[]='c.id=?';$args[]=$component;}if(ctype_digit($year)){$where[]='s.reporting_year=?';$args[]=(int)$year;}$sql="SELECT s.id,p.project_code,p.project_name,p.region,p.countries,c.code component_code,c.name component_name,si.code subindicator_code,si.name subindicator_name,si.indicator_type,i.code geb_code,i.name geb_name,s.reporting_year,s.country,s.reported_value,s.unit,s.result_text,s.disaggregation,s.data_source,s.methodology,s.notes,s.evidence_path,s.state,u.name submitter,u.username submitter_username,u.email submitter_email,r.name reviewer,r.username reviewer_username,r.email reviewer_email,a.name approver,a.username approver_username,a.email approver_email,s.created_at,s.updated_at,s.approved_at FROM subindicator_submissions s JOIN projects p ON p.id=s.project_id JOIN sub_indicators si ON si.id=s.sub_indicator_id JOIN components c ON c.id=si.component_id LEFT JOIN indicators i ON i.id=s.geb_indicator_id JOIN users u ON u.id=s.submitted_by LEFT JOIN users r ON r.id=s.reviewer_id LEFT JOIN users a ON a.id=s.approver_id ".($where?'WHERE '.implode(' AND ',$where):'')." ORDER BY s.updated_at DESC,s.id DESC";$st=$pdo->prepare($sql);$st->execute($args);$rows=$st->fetchAll();$headers=['Submission ID','Project Code','Project Name','Region','Project Countries','Component Code','Component Name','Sub-indicator Code','Sub-indicator Name','Indicator Type','Linked GEB Code','Linked GEB Name','Reporting Year','Country','Reported Value','Unit','Result / Achievement','Disaggregation / Details','Data Source','Calculation / Assessment Methodology','Notes','Evidence File','Workflow Status','Submitter','Submitter Username','Submitter Email','Reviewer','Reviewer Username','Reviewer Email','Approver','Approver Username','Approver Email','Created At','Updated At','Approved At'];$matrix=[];foreach($rows as $r)$matrix[]=[(int)$r['id'],$r['project_code'],$r['project_name'],$r['region'],$r['countries'],$r['component_code'],$r['component_name'],$r['subindicator_code'],$r['subindicator_name'],$r['indicator_type'],$r['geb_code'],$r['geb_name'],(int)$r['reporting_year'],$r['country'],$r['reported_value']!==null?(float)$r['reported_value']:'',$r['unit'],$r['result_text'],$r['disaggregation'],$r['data_source'],$r['methodology'],$r['notes'],$r['evidence_path'],$r['state'],$r['submitter'],$r['submitter_username'],$r['submitter_email'],$r['reviewer'],$r['reviewer_username'],$r['reviewer_email'],$r['approver'],$r['approver_username'],$r['approver_email'],$r['created_at'],$r['updated_at'],$r['approved_at']];
if($format==='csv'){header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment; filename="islands_subindicator_export_'.date('Ymd_His').'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,$headers);foreach($matrix as $row)fputcsv($out,$row);fclose($out);exit;}
if($format!=='xlsx'){http_response_code(400);exit('Unsupported export format. Use csv or xlsx.');}if(!class_exists('ZipArchive')){http_response_code(500);exit('PHP ZipArchive is required for XLSX export. Enable the zip extension or use CSV.');}
$tmp=tempnam(sys_get_temp_dir(),'islands_xlsx_');$zip=new ZipArchive();$zip->open($tmp,ZipArchive::OVERWRITE|ZipArchive::CREATE);$esc=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$sheet='<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/><selection pane="bottomLeft" activeCell="A2" sqref="A2"/></sheetView></sheetViews><sheetData>';$rowNo=1;$colName=function($n){$s='';while($n>0){$n--; $s=chr(65+$n%26).$s;$n=intdiv($n,26);}return $s;};$addRow=function($vals,$rno)use(&$sheet,$esc,$colName){$sheet.='<row r="'.$rno.'">';foreach(array_values($vals) as $i=>$v){$ref=$colName($i+1).$rno;if(is_numeric($v)&&$v!==''&&!is_string($v))$sheet.='<c r="'.$ref.'"><v>'.(float)$v.'</v></c>';else{$text=(string)$v;$sheet.='<c r="'.$ref.'" t="inlineStr"><is><t xml:space="preserve">'.$esc($text).'</t></is></c>';}}$sheet.='</row>';};$addRow($headers,$rowNo++);foreach($matrix as $row)$addRow($row,$rowNo++);$sheet.='</sheetData><autoFilter ref="A1:'.$colName(count($headers)).max(1,$rowNo-1).'"/></worksheet>';$zip->addFromString('xl/worksheets/sheet1.xml',$sheet);$zip->addFromString('[Content_Types].xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>');$zip->addFromString('_rels/.rels','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="ht